<script setup lang="ts">
import { computed, ref } from 'vue'
import { projects, tasks, addProject, updateProject, deleteProject } from '../stores'
import type { Project } from '../stores'
const show=ref(false), editing=ref<Project|null>(null), form=ref({name:'',description:'',color:'#4f46e5',status:'active' as Project['status']})
const projectTasks=(name:string)=>tasks.value.filter(t=>t.project===name).length
function open(p?:Project){ editing.value=p||null; form.value=p?{name:p.name,description:p.description,color:p.color,status:p.status}:{name:'',description:'',color:'#4f46e5',status:'active'};show.value=true }
function save(){if(!form.value.name.trim())return; editing.value?updateProject({...editing.value,...form.value}):addProject({...form.value});show.value=false}
</script>
<template><main class="page"><div class="page-heading page-heading-row"><div><p class="eyebrow">WORKSPACE</p><h1>Projects</h1><p>Organize your tasks by project and track progress.</p></div><button class="primary-btn" @click="open()">＋ New Project</button></div><section class="project-grid"><article v-for="p in projects" :key="p.id" class="project-card"><div class="project-top"><span class="project-dot" :style="{background:p.color}"></span><span class="status-badge" :class="p.status">{{p.status}}</span></div><h3>{{p.name}}</h3><p>{{p.description}}</p><div class="project-meta"><span>{{projectTasks(p.name)}} tasks</span><div><button @click="open(p)">Edit</button><button class="danger-link" @click="deleteProject(p.id)">Delete</button></div></div></article></section><div v-if="show" class="modal-backdrop" @click.self="show=false"><form class="dialog" @submit.prevent="save"><div class="dialog-head"><div><p class="eyebrow">PROJECT</p><h2>{{editing?'Edit project':'New project'}}</h2></div><button type="button" class="close-btn" @click="show=false">×</button></div><label>Name<input v-model="form.name" placeholder="e.g. Website redesign" required></label><label>Description<textarea v-model="form.description" rows="3" placeholder="What is this project about?"></textarea></label><div class="form-grid"><label>Status<select v-model="form.status"><option value="active">Active</option><option value="on-hold">On hold</option><option value="completed">Completed</option></select></label><label>Color<input v-model="form.color" type="color"></label></div><div class="dialog-actions"><button type="button" class="secondary-btn" @click="show=false">Cancel</button><button class="primary-btn">{{editing?'Save changes':'Create project'}}</button></div></form></div></main></template>
